(() => {
  'use strict';
  const KEY='thoughtflow-v1', app=document.getElementById('app');
  const id=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,7);
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const sample=()=>({id:id(),name:'视频创作',folders:[{id:'ideas',name:'灵感'},{id:'refs',name:'参考'}],notes:[{id:'n1',folder:'ideas',title:'关于这支视频',body:'我想拍一支关于重新找回生活节奏的视频。\n\n希望它不是说教，而是分享真实的小方法：整理房间、写下想法，每天完成一件小事。\n\n画面温暖自然，时长三分钟左右。先写大纲，再决定要拍哪些镜头。'},{id:'n2',folder:'refs',title:'画面参考',body:'自然光、日常场景。可以拍桌面、散步和写字的镜头。'}],selectedNote:'n1',summary:'',feedback:'',level:2,tasks:[],sourceDirty:true});
  let state; try{state=JSON.parse(localStorage.getItem(KEY))}catch(_){}
  if(!state||!Array.isArray(state.projects)||!state.projects.length){const p=sample();state={projects:[p],current:p.id,stage:0}}
  let storageConflict=false;
  const save=()=>{if(storageConflict)return;try{localStorage.setItem(KEY,JSON.stringify(state))}catch(_){toast('保存失败，请检查浏览器存储空间')}};
  const current=()=>state.projects.find(x=>x.id===state.current)||state.projects[0];
  function normalize(p){p.folders=Array.isArray(p.folders)?p.folders:[];p.notes=Array.isArray(p.notes)?p.notes:[];p.tasks=Array.isArray(p.tasks)?p.tasks:[];p.level=Math.max(1,Math.min(3,Number(p.level)||2));p.summary=p.summary||'';p.feedback=p.feedback||'';p.folders.forEach(f=>{if(!f.id)f.id=id()});p.notes.forEach(n=>{if(!n.id)n.id=id();n.body=n.body||'';n.title=n.title||'未命名笔记'});p.tasks.forEach(t=>{if(!t.id)t.id=id();t.trigger=t.trigger||''});}
  state.projects.forEach(normalize);state.stage=Math.max(0,Math.min(2,Number(state.stage)||0));
  let toastTimer, stageObserver;
  function toast(msg){let el=document.querySelector('.toast');if(!el){el=document.createElement('div');el.className='toast';el.setAttribute('role','status');document.body.appendChild(el)}el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3000)}
  const notesText=p=>p.notes.filter(n=>n.body.trim()).map(n=>n.body.trim()).join('\n\n');
  const compact=s=>s.replace(/\s+/g,' ').trim();
  // Each request receives a snapshot of exactly one project; the server holds the only model key.
  const pending=new Map(), epochs=new Map(); let switchEpoch=0;
  let modelStatus={loaded:false,configured:false,model:''};
  const mark=p=>epochs.set(p.id,(epochs.get(p.id)||0)+1);
  function projectContext(p){return {id:p.id,name:p.name,notes:p.notes.map(n=>({id:n.id,title:n.title,body:n.body,folder:n.folder})),summary:p.summary||'',feedback:p.feedback||'',feedbackHistory:Array.isArray(p.feedbackHistory)?p.feedbackHistory:(p.feedbackApplied?[p.feedbackApplied]:[]),tasks:p.tasks.map(t=>({id:t.id,text:t.text,done:!!t.done,trigger:t.trigger||''})),level:p.level}}
  const fingerprint=p=>JSON.stringify(projectContext(p));
  function serverLabel(){return !modelStatus.loaded?'正在检查模型连接…':modelStatus.configured?'模型：'+modelStatus.model+' · 内容将发送至模型服务商':'模型尚未配置，请先设置服务端 API 密钥'}
  function syncServerStatus(){document.querySelectorAll('.model-availability').forEach(el=>el.textContent=serverLabel())}
  async function checkServer(){try{const r=await fetch('/api/status',{cache:'no-store'});if(!r.ok)throw Error();const x=await r.json();modelStatus={loaded:true,configured:x.configured===true,model:typeof x.model==='string'?x.model:''}}catch(_){modelStatus={loaded:true,configured:false,model:''}}syncServerStatus()}
  function validSummary(x){return typeof x==='string'&&x.trim()&&x.length<=30000}
  function validTasks(x){if(!Array.isArray(x)||x.length>50)return null;const items=[];for(const t of x){if(!t||typeof t.text!=='string'||!t.text.trim()||t.text.length>300||typeof t.trigger!=='string'||t.trigger.length>200)return null;items.push({text:t.text.trim(),trigger:t.trigger.trim()})}return items}
  async function generate(p,mode){
    if(storageConflict){toast('请先导出需要保留的内容，再刷新页面');return}
    if(pending.size){toast('正在处理上一次请求，请稍候');return}
    const context=projectContext(p);if(!context.notes.some(n=>n.body.trim())&&!context.summary.trim()){toast('先写下原文或整理内容');return}
    if(mode==='feedback'&&!context.feedback.trim()){toast('先写下修改意见');return}
    if(mode==='summary'&&p.summary.trim()&&!confirm('生成新整理会替换当前内容。继续吗？'))return;
    const requestEpoch=epochs.get(p.id)||0, requestSwitch=switchEpoch, before=fingerprint(p), controller=new AbortController();
    pending.set(p.id,controller);app.querySelectorAll('[data-generate]').forEach(b=>{b.disabled=true});toast('正在生成…');
    const timeout=setTimeout(()=>controller.abort(),90000);
    try{
      const res=await fetch('/api/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode,project:context}),signal:controller.signal});
      let data;try{data=await res.json()}catch(_){throw Error('服务返回了无法读取的结果')}
      if(!res.ok)throw Error(typeof data.error==='string'?data.error:'生成失败，请重试');
      if(storageConflict||state.current!==p.id||switchEpoch!==requestSwitch||(epochs.get(p.id)||0)!==requestEpoch||fingerprint(p)!==before){toast('项目内容已变化，本次结果未应用，请重新生成');return}
      if(mode==='tasks'){
        const tasks=validTasks(data.tasks);if(!tasks)throw Error('模型返回的任务格式有误，请重试');if(!tasks.length){toast('没有需要补充的任务');return}
        p.generatedDraft=tasks;p.draftSnapshot=before;
      }else{
        if(!validSummary(data.summary))throw Error('模型返回的整理格式有误，请重试');
        p.summary=data.summary.trim();p.summaryEdited=false;if(mode==='summary')p.sourceDirty=false;
        if(mode==='feedback'){p.feedbackHistory=[...(Array.isArray(p.feedbackHistory)?p.feedbackHistory:(p.feedbackApplied?[p.feedbackApplied]:[])),p.feedback].slice(-20);p.feedbackApplied=p.feedback;p.feedback='';p.feedbackResult='已按修改意见更新。'}
      }
      mark(p);save();render();toast(mode==='tasks'?'草稿已生成，请检查后加入清单':'整理已更新，可以直接编辑');
    }catch(e){const message=e.name==='AbortError'?'请求超时，请重试':(e.message||'生成失败，请重试');toast(message)}
    finally{clearTimeout(timeout);pending.delete(p.id);if(state.current===p.id)app.querySelectorAll('[data-generate]').forEach(b=>{b.disabled=false})}
  }
  function backupExport(){const blob=new Blob([JSON.stringify({format:'thoughtflow-backup',version:1,projects:state.projects,current:state.current},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='清单法备份.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
  function cleanBackup(data){
    const projects=data&&data.format==='thoughtflow-backup'&&data.version===1&&data.projects;
    if(!Array.isArray(projects)||!projects.length||projects.length>100)throw Error('备份格式不正确');
    const text=(v,max)=>{if(typeof v!=='string'||v.length>max)throw Error('备份包含无效内容');return v};const ids=new Set();
    const clean=projects.map(p=>{if(!p||typeof p!=='object')throw Error('备份格式不正确');const pid=text(p.id,200);if(!pid||ids.has(pid))throw Error('备份项目编号无效');ids.add(pid);if(!Array.isArray(p.folders)||p.folders.length>500||!Array.isArray(p.notes)||p.notes.length>5000||!Array.isArray(p.tasks)||p.tasks.length>5000)throw Error('备份数据过大或格式不正确');return {id:pid,name:text(p.name,500),folders:p.folders.map(f=>({id:text(f.id,200),name:text(f.name,500)})),notes:p.notes.map(n=>({id:text(n.id,200),folder:text(n.folder||'',200),title:text(n.title||'',500),body:text(n.body||'',500000)})),selectedNote:typeof p.selectedNote==='string'?p.selectedNote:null,summary:text(p.summary||'',500000),feedback:text(p.feedback||'',30000),feedbackApplied:text(p.feedbackApplied||'',30000),feedbackHistory:(Array.isArray(p.feedbackHistory)?p.feedbackHistory.slice(-20).map(x=>text(x,12000)):[]),level:Math.max(1,Math.min(3,Number(p.level)||2)),tasks:p.tasks.map(t=>({id:text(t.id,200),text:text(t.text,1000),trigger:text(t.trigger||'',500),done:!!t.done,manual:!!t.manual,generated:!!t.generated})),sourceDirty:!!p.sourceDirty}});
    return {projects:clean,current:ids.has(data.current)?data.current:clean[0].id,stage:0};
  }
  async function backupImport(input){const file=input.files?.[0];input.value='';if(!file)return;if(file.size>10*1024*1024){toast('备份文件不能超过 10 MB');return}try{const next=cleanBackup(JSON.parse(await file.text()));if(!confirm('恢复备份会替换此浏览器中的全部项目。请先导出当前备份。继续吗？'))return;switchEpoch++;state=next;state.projects.forEach(normalize);save();render();toast('备份已恢复')}catch(e){toast(e.message||'无法读取备份文件')}}
  function render(){
    const p=current();normalize(p);state.current=p.id;
    const n=p.notes.find(x=>x.id===p.selectedNote)||p.notes[0];if(n)p.selectedNote=n.id;
    const done=p.tasks.filter(t=>t.done).length, count=p.tasks.length;
    app.innerHTML=`<div class="app-shell"><header class="app-header"><div class="brand"><span class="brand-mark">●</span><span>清单法</span></div><div class="project-picker"><select id="project-select" aria-label="切换项目">${state.projects.map(x=>`<option value="${esc(x.id)}" ${x.id===p.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><button class="icon-btn" data-action="new-project" aria-label="新建项目">＋</button><details class="backup-menu"><summary>备份</summary><div><button class="btn btn-muted backup-btn" data-action="export-backup">导出备份</button><button class="btn btn-muted backup-btn" data-action="choose-backup">恢复备份</button><input id="backup-file" type="file" accept="application/json,.json" hidden></div></details></div></header><div class="project-heading"><div class="eyebrow">PROJECT / ${esc(String(state.projects.findIndex(x=>x.id===p.id)+1).padStart(2,'0'))}</div><h1>${esc(p.name)}</h1><span class="project-caption">内容保存在此浏览器</span></div><nav class="flow-nav" aria-label="切换层级">${['原文','整理','清单'].map((s,i)=>`<button class="flow-tab ${state.stage===i?'active':''}" data-stage="${i}" ${state.stage===i?'aria-current="step"':''}><span class="tab-index">0${i+1}</span><span>${s}</span></button>`).join('')}</nav><div class="flow-meter"><span id="flow-meter-fill" style="--stage-index:${state.stage}"></span></div><main class="stage-viewport"><div class="stage-track" id="stage-track" style="--stage-index:${state.stage}"><section class="stage stage-notes" aria-label="原文">${notesView(p,n)}</section><section class="stage stage-summary" aria-label="整理">${summaryView(p)}</section><section class="stage stage-tasks" aria-label="清单">${tasksView(p,done,count)}</section></div></main><div class="mobile-hint">左右滑动切换</div></div>`;
    setStage(state.stage,false);
    if(stageObserver)stageObserver.disconnect();
    if(typeof ResizeObserver!=='undefined'){stageObserver=new ResizeObserver(fitStage);document.querySelectorAll('.stage').forEach(el=>stageObserver.observe(el))}
  }
  function notesView(p,n){return `<div class="stage-top"><div><span class="eyebrow">01 / NOTES</span><h2>原文</h2><p>先写下来，不必整理。</p></div><span class="stage-count">${p.notes.length} <small>篇</small></span></div><div class="notes-view"><aside class="folder-list"><div class="section-head"><span>文件夹</span><button class="icon-btn" data-action="add-folder" aria-label="新建文件夹">＋</button></div>${p.folders.map(f=>`<div class="folder"><div class="folder-heading"><strong>${esc(f.name)}</strong><div><button class="icon-btn" data-action="rename-folder" data-id="${esc(f.id)}" aria-label="重命名文件夹">⋯</button><button class="icon-btn" data-action="add-note" data-folder="${esc(f.id)}" aria-label="在 ${esc(f.name)} 新建笔记">＋</button></div></div>${p.notes.filter(x=>x.folder===f.id).map(x=>`<button class="note-item ${n?.id===x.id?'active':''}" data-action="select-note" data-id="${esc(x.id)}"><span>${esc(x.title)}</span><span>↗</span></button>`).join('')}</div>`).join('')}<button class="btn btn-muted add-note" data-action="add-note">＋ 新建笔记</button></aside><div class="note-editor">${n?`<div class="editor-tools"><span>编辑中</span><button class="icon-btn" data-action="delete-note" aria-label="删除笔记">×</button></div><input id="note-title" class="note-title" aria-label="笔记标题" placeholder="无标题" value="${esc(n.title)}"><textarea id="note-body" class="note-body" aria-label="原文内容" placeholder="把想到的事写在这里…">${esc(n.body)}</textarea><div class="editor-foot"><span>自动保存</span><span id="word-count">${n.body.length} 字</span></div>`:`<div class="empty"><p>这里还没有笔记。</p><button class="btn btn-primary" data-action="add-note">新建笔记</button></div>`}</div></div><div class="bottom-action"><span>下一步</span><button class="btn btn-primary" data-stage="1">整理这些想法 <span>↗</span></button></div>`}
  function summaryView(p){const completed=p.tasks.filter(t=>t.done).length;return `<div class="stage-top"><div><span class="eyebrow">02 / ORGANIZE</span><h2>整理</h2><p>检查内容，有偏差就直接改。</p></div><span class="stage-mark">↗</span></div><div class="summary-view"><div class="demo-note"><span class="model-availability">${esc(serverLabel())}</span><p>生成时会将当前项目的原文、整理与清单发送给模型服务商。项目数据仍保存在当前浏览器。</p></div><div class="section-head"><div><span class="eyebrow">CURRENT DRAFT</span><h3>当前整理</h3></div><button class="btn btn-muted" data-action="make-summary" data-generate>从原文生成</button></div><div class="source-state" id="source-state">${p.sourceDirty?'原文有更新，整理可能需要重新生成':'来自当前项目的原文'}</div><textarea class="summary-editor" id="summary" aria-label="整理内容" placeholder="点击“从原文生成”，或者直接写下整理结果。">${esc(p.summary)}</textarea><div class="feedback-box"><label for="feedback">修改意见</label><p>描述你希望如何调整；模型会参考当前项目的原文和清单。</p><div class="feedback-row"><textarea id="feedback" aria-label="修改意见" placeholder="写下具体修改…">${esc(p.feedback)}</textarea><button class="btn btn-primary" data-action="apply-feedback" data-generate>应用修改 <span>↗</span></button></div><span class="feedback-result" id="feedback-result">${esc(p.feedbackResult||'')}</span></div><div class="context-strip"><span>项目上下文</span><p><b>${p.notes.length}</b> 篇原文 · <b>${p.tasks.length}</b> 项任务 · 已完成 <b>${completed}</b></p><small>清单草稿会参考当前原文和整理；清单修改保存在同一项目中。</small><div class="task-context-list" id="task-context-list">${contextTasks(p)}</div></div><div class="bottom-action"><span>把方向变成行动</span><button class="btn btn-primary" data-stage="2">查看清单 <span>↗</span></button></div></div>`}
  function tasksView(p,done,count){const pct=count?Math.round(done/count*100):0;return `<div class="stage-top"><div><span class="eyebrow">03 / DO</span><h2>行动清单</h2><p>一次看清一件事。</p></div><span class="stage-count">${done}<small> / ${count}</small></span></div><div class="tasks-view"><div class="progress"><div><span>完成进度</span><strong>${pct}%</strong></div><div class="progress-line"><i style="width:${pct}%"></i></div></div><div class="section-head task-heading"><div><span class="eyebrow">NEXT UP</span><h3>要做的事</h3></div><button class="btn btn-muted" data-action="add-task">＋ 添加</button></div><div class="task-list" id="task-list">${p.tasks.length?p.tasks.map(taskRow).join(''):'<div class="empty">还没有任务。可以添加一项，或从下方草稿开始。</div>'}</div><div class="detail-control"><div class="section-head"><div><span class="eyebrow">BREAK IT DOWN</span><h3>拆到多细？</h3></div><strong id="level-name">${['概览','适中','细致'][p.level-1]}</strong></div><input id="level" type="range" min="1" max="3" step="1" value="${p.level}" aria-label="任务细节程度"><div class="range-labels"><span>概览</span><span>适中</span><span>细致</span></div><p>先选能在约 15 分钟内开始的动作，时间由你决定。</p><div class="preview-label">草稿预览 <span id="preview-count"></span></div><div class="draft-preview" id="draft-preview">${previewHTML(p)}</div><button class="btn btn-primary full" data-action="generate-tasks" data-generate>生成任务草稿 <span>↗</span></button><button class="btn btn-muted full" data-action="add-draft">将草稿加入清单</button><small class="demo-disclaimer">生成后请检查草稿；已有任务不会被覆盖。</small></div><div class="context-strip"><span>依据</span><p id="task-context">${esc(compact(p.summary||notesText(p)).slice(0,100)||'先在原文中写下想法。')}</p><small>当前项目的原文和整理会用于草稿预览。</small></div></div>`}
  function contextTasks(p){return p.tasks.length ? p.tasks.map(t=>`<div>${t.done?'✓':'○'} ${esc(t.text)}</div>`).join('') : '<div>清单中还没有任务</div>'}
  function taskRow(t){return `<div class="task-row ${t.done?'done':''}" data-task-row="${esc(t.id)}"><button class="drag-handle" data-drag="${esc(t.id)}" aria-label="拖动排序">⠿</button><input class="task-check" type="checkbox" data-action="toggle-task" data-id="${esc(t.id)}" ${t.done?'checked':''} aria-label="完成 ${esc(t.text)}"><div class="task-content"><input class="task-input" data-task-id="${esc(t.id)}" value="${esc(t.text)}" aria-label="任务内容"><div class="task-intention"><span>如果</span><input class="trigger-input" data-trigger-id="${esc(t.id)}" value="${esc(t.trigger||'')}" placeholder="填写时间或情境" aria-label="行动触发条件"><span>，那么就做这件事</span></div></div><div class="task-controls"><button class="icon-btn" data-action="move-up" data-id="${esc(t.id)}" aria-label="上移">↑</button><button class="icon-btn" data-action="move-down" data-id="${esc(t.id)}" aria-label="下移">↓</button><button class="icon-btn" data-action="delete-task" data-id="${esc(t.id)}" aria-label="删除">×</button></div></div>`}
  function previewHTML(p){const items=Array.isArray(p.generatedDraft)?p.generatedDraft:[];if(!items.length)return '<div class="empty">选择细节程度，再生成任务草稿。</div>';if(p.draftSnapshot!==fingerprint(p))return '<div class="empty">项目内容或细节程度已更改，请重新生成草稿。</div>';return items.map((x,i)=>`<div class="preview-row"><span>${String(i+1).padStart(2,'0')}</span><p>${esc(x.text)}${x.trigger?' · 如果 '+esc(x.trigger):''}</p></div>`).join('')}
  function fitStage(){const track=document.getElementById('stage-track'),viewport=app.querySelector?.('.stage-viewport'),active=track?.children?.[state.stage];if(viewport&&active){const height=active.offsetHeight;if(height&&viewport.style.height!==height+'px')viewport.style.height=height+'px'}}
  function setStage(stage,animate=true){const previous=state.stage;state.stage=Math.max(0,Math.min(2,stage));const track=document.getElementById('stage-track');if(!track)return;if(!animate)track.style.transition='none';track.style.setProperty('--stage-index',state.stage);Array.from(track.children||[]).forEach((panel,i)=>{panel.inert=i!==state.stage;panel.setAttribute('aria-hidden',i===state.stage?'false':'true')});document.getElementById('flow-meter-fill')?.style.setProperty('--stage-index',state.stage);app.querySelectorAll('.flow-tab').forEach((x,i)=>{x.classList.toggle('active',i===state.stage);if(i===state.stage)x.setAttribute('aria-current','step');else x.removeAttribute('aria-current')});if(!animate)requestAnimationFrame(()=>track.style.transition='');requestAnimationFrame(fitStage);if(animate&&previous!==state.stage){const nav=app.querySelector?.('.flow-nav');if(nav&&nav.getBoundingClientRect().top<0)nav.scrollIntoView({behavior:'smooth',block:'start'})}save()}
  function refreshDerived(p){const preview=document.getElementById('draft-preview');if(preview)preview.innerHTML=previewHTML(p);const context=document.getElementById('task-context');if(context)context.textContent=compact(p.summary||notesText(p)).slice(0,100)||'先在原文中写下想法。';const list=document.getElementById('task-context-list');if(list)list.innerHTML=contextTasks(p);const status=document.getElementById('source-state');if(status)status.textContent=p.sourceDirty?'原文有更新，整理可能需要重新生成':'来自当前项目的原文';requestAnimationFrame(fitStage)}
  app.addEventListener('click',e=>{const s=e.target.closest('[data-stage]');if(s){setStage(Number(s.dataset.stage));return}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,p=current();if(a==='toggle-task')return;if(a==='make-summary'){generate(p,'summary');return}if(a==='apply-feedback'){generate(p,'feedback');return}if(a==='generate-tasks'){generate(p,'tasks');return}if(a==='export-backup'){backupExport();return}if(a==='choose-backup'){document.getElementById('backup-file').click();return}
    if(a==='new-project'){switchEpoch++;const name=prompt('新项目名称');if(!name?.trim())return;const f={id:id(),name:'笔记'};const next={id:id(),name:name.trim(),folders:[f],notes:[],selectedNote:null,summary:'',feedback:'',level:2,tasks:[],sourceDirty:true};state.projects.push(next);state.current=next.id;state.stage=0}
    else if(a==='add-folder'){const name=prompt('文件夹名称');if(!name?.trim())return;p.folders.push({id:id(),name:name.trim()})}
    else if(a==='rename-folder'){const f=p.folders.find(x=>x.id===b.dataset.id);if(!f)return;const name=prompt('修改文件夹名称',f.name);if(!name?.trim())return;f.name=name.trim()}
    else if(a==='add-note'){if(!p.folders.length)p.folders.push({id:id(),name:'笔记'});const n={id:id(),folder:b.dataset.folder||p.folders[0].id,title:'未命名笔记',body:''};p.notes.push(n);p.selectedNote=n.id;p.sourceDirty=true}
    else if(a==='select-note')p.selectedNote=b.dataset.id;
    else if(a==='delete-note'){if(!confirm('删除这篇笔记？此操作不能撤销。'))return;p.notes=p.notes.filter(x=>x.id!==p.selectedNote);p.selectedNote=p.notes[0]?.id||null;p.sourceDirty=true}
    else if(a==='add-task'){const text=prompt('写下一个具体动作');if(!text?.trim())return;p.tasks.push({id:id(),text:text.trim(),done:false,trigger:'',manual:true})}
    else if(a==='delete-task'){const t=p.tasks.find(x=>x.id===b.dataset.id);if(!t)return;if(!confirm('删除这项任务？'))return;p.tasks=p.tasks.filter(x=>x.id!==b.dataset.id)}
    else if(a==='move-up'||a==='move-down'){const i=p.tasks.findIndex(x=>x.id===b.dataset.id),j=i+(a==='move-up'?-1:1);if(i<0||j<0||j>=p.tasks.length)return;[p.tasks[i],p.tasks[j]]=[p.tasks[j],p.tasks[i]]}
    else if(a==='add-draft'){if(!Array.isArray(p.generatedDraft)||p.draftSnapshot!==fingerprint(p)){toast('请先根据当前项目生成草稿');return}const existing=new Set(p.tasks.map(x=>x.text.trim()));const draft=p.generatedDraft.filter(x=>!existing.has(x.text));if(!draft.length){toast('没有新的草稿可添加');return}draft.forEach(x=>p.tasks.push({id:id(),text:x.text,done:false,trigger:x.trigger,generated:true}));p.generatedDraft=[];p.draftSnapshot='';toast('已添加 '+draft.length+' 项，可继续编辑')}
    mark(p);save();render();
  });
  app.addEventListener('change',e=>{const p=current();if(e.target.id==='backup-file'){backupImport(e.target);return}if(e.target.id==='project-select'){switchEpoch++;state.current=e.target.value;state.stage=0;save();render();return}if(e.target.matches('[data-action="toggle-task"]')){const t=p.tasks.find(x=>x.id===e.target.dataset.id);if(t){t.done=e.target.checked;mark(p)}save();render()}});
  app.addEventListener('input',e=>{const p=current(),n=p.notes.find(x=>x.id===p.selectedNote);if(e.target.id==='note-title'&&n){n.title=e.target.value;p.sourceDirty=true}if(e.target.id==='note-body'&&n){n.body=e.target.value;p.sourceDirty=true;const wc=document.getElementById('word-count');if(wc)wc.textContent=n.body.length+' 字'}if(e.target.id==='summary'){p.summary=e.target.value;p.summaryEdited=true}if(e.target.id==='feedback')p.feedback=e.target.value;if(e.target.id==='level'){p.level=Number(e.target.value);document.getElementById('level-name').textContent=['概览','适中','细致'][p.level-1]}if(e.target.dataset.taskId){const t=p.tasks.find(x=>x.id===e.target.dataset.taskId);if(t){t.text=e.target.value;t.manual=true}}if(e.target.dataset.triggerId){const t=p.tasks.find(x=>x.id===e.target.dataset.triggerId);if(t)t.trigger=e.target.value}mark(p);refreshDerived(p);save()});
  let sx=0,sy=0,swipe=false;app.addEventListener('touchstart',e=>{if(e.target.closest('input,textarea,select,button,.task-row')){swipe=false;return}sx=e.touches[0].clientX;sy=e.touches[0].clientY;swipe=true},{passive:true});app.addEventListener('touchend',e=>{if(!swipe)return;const dx=e.changedTouches[0].clientX-sx,dy=e.changedTouches[0].clientY-sy;swipe=false;if(Math.abs(dx)>55&&Math.abs(dx)>Math.abs(dy)*1.3)setStage(state.stage+(dx<0?1:-1))},{passive:true});
  let pointerDrag=null;
  function clearDragStyles(){app.querySelectorAll('.dragging,.drag-over').forEach(x=>x.classList.remove('dragging','drag-over'))}
  app.addEventListener('pointerdown',e=>{const handle=e.target.closest('[data-drag]');if(!handle||e.button!==0)return;e.preventDefault();pointerDrag={id:handle.dataset.drag,startY:e.clientY,startX:e.clientX,moved:false};handle.setPointerCapture?.(e.pointerId);handle.closest('.task-row')?.classList.add('dragging')});
  app.addEventListener('pointermove',e=>{if(!pointerDrag)return;if(Math.abs(e.clientY-pointerDrag.startY)+Math.abs(e.clientX-pointerDrag.startX)>4)pointerDrag.moved=true;app.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'));const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-task-row]');if(target&&target.dataset.taskRow!==pointerDrag.id)target.classList.add('drag-over')});
  app.addEventListener('pointerup',e=>{if(!pointerDrag)return;const from=pointerDrag.id,moved=pointerDrag.moved;pointerDrag=null;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-task-row]');clearDragStyles();if(moved&&target&&target.dataset.taskRow!==from)moveTo(from,target.dataset.taskRow)});
  app.addEventListener('pointercancel',()=>{pointerDrag=null;clearDragStyles()});
  function moveTo(from,to){const p=current(),a=p.tasks.findIndex(t=>t.id===from),b=p.tasks.findIndex(t=>t.id===to);if(a<0||b<0||a===b)return;const [item]=p.tasks.splice(a,1);p.tasks.splice(b,0,item);mark(p);save();render();toast('顺序已更新')}
  window.addEventListener('storage',e=>{if(e.key!==KEY)return;storageConflict=true;let bar=document.getElementById('storage-conflict');if(!bar){bar=document.createElement('div');bar.id='storage-conflict';bar.setAttribute('role','alert');bar.textContent='另一个标签页修改了项目，本页已暂停保存。请先导出需要保留的内容，再刷新页面。';document.body.prepend(bar)}});
  render();checkServer();
})();
